const explicit = process.env.REPORTER_VARIANT === 'explicit';
module.exports = {
  testMatch: ['<rootDir>/tests/**/*.test.js'],
  reporters: [['jest-junit', {
    outputDirectory: 'reports',
    outputName: `jest-junit-${explicit ? 'explicit' : 'default'}.xml`,
    noStackTrace: 'true',
    ...(explicit ? {
      addFileAttribute: 'true',
      reportTestSuiteErrors: 'true',
      classNameTemplate: 'custom class label',
      suiteNameTemplate: 'custom suite label',
    } : {}),
  }]],
};
